import test from 'node:test';
import assert from 'node:assert/strict';
import {Chess} from '../../../../lib/chess.js';
import {openResearchData} from '../../../data-policy.mjs';
import {boardFen} from '../../FRIEND-shared/lib.mjs';
import {fixtures} from './fixtures.mjs';
import {savedPanels,withSavedPanel} from './saved-panels.mjs';
import {explainMove} from './advantage.mjs';
import {checkWitness} from './check-witness.mjs';
import {explainMove as parent} from '../../E149-minority-structure/code/minority.mjs';
await openResearchData(['D001'],{purpose:'test'});const saved=await savedPanels(),f=fixtures[0],sf=withSavedPanel(f,saved),sr=explainMove(sf),df=fixtures[2],di=withSavedPanel(df,saved),dr=explainMove(di),own=r=>r.events.filter(e=>e.evidence?.experiment==='E150');
for(const fixture of fixtures)test(fixture.id,()=>{const r=explainMove(withSavedPanel(fixture,saved));assert.deepEqual(own(r).map(e=>e.id),fixture.expected);assert.deepEqual(r.events.filter(e=>e.evidence?.experiment!=='E150'),parent(fixture).events);if(r.advantageResourceAnalysis.witness)checkWitness(r.advantageResourceAnalysis.witness,r,fixture);});
test('disabled exactly parent',()=>{for(const advantageResourceTags of [undefined,false]){const i={...df,advantageResourceTags,maxAdvantageResourceNodes:null,advantageAlternative:null,advantageResourcePanel:null};assert.deepEqual(explainMove(i),parent(i));}});
test('strict controls and actual alternative identity',()=>{for(const advantageResourceTags of [null,1,'true'])assert.throws(()=>explainMove({...di,advantageResourceTags}));for(const maxAdvantageResourceNodes of [null,-1,50001,0.5])assert.throws(()=>explainMove({...di,maxAdvantageResourceNodes}));for(const advantageAlternative of [null,4,df.move,'e5e6','e2e3'])assert.throws(()=>explainMove({...di,advantageAlternative}));assert.throws(()=>explainMove({...di,advantageResourcePanel:null}));});
test('fresh versus saved output and charge',()=>{assert.deepEqual(explainMove(f),sr);assert.deepEqual(explainMove(df),dr);});
test('exact and one-short atomic cap',()=>{const n=dr.advantageResourceAnalysis.nodes;assert.equal(explainMove({...di,maxAdvantageResourceNodes:n}).advantageResourceAnalysis.status,'proven');for(const i of [df,di]){const j={...i,maxAdvantageResourceNodes:n-1},r=explainMove(j);assert.equal(r.advantageResourceAnalysis.status,'exhausted');assert.equal(r.advantageResourceAnalysis.nodes,n);assert.equal(r.advantageResourceAnalysis.witness,null);assert.deepEqual(r.events,parent(j).events);assert.equal(r.comment,parent(j).comment);}});
test('static full two-opponent-turn policy and failed attempts retained',()=>{const w=sr.advantageResourceAnalysis.witness;assert.equal(w.staticEdge.minimum,4);assert.equal(w.panel.baseline,4);assert.ok(w.staticEdge.policy.every(b=>b.chosen!==null));assert.equal(w.staticEdge.policy.length,w.panel.variants[0].legal.length);assert.ok(w.panel.variants[0].branches.some(b=>b.attempts.some(a=>a.counters.some(c=>c.balance<3||Object.values(c.flags).some(Boolean)))));});
test('dynamic baseline, actual identity and alternative failure',()=>{const w=dr.advantageResourceAnalysis.witness;assert.equal(w.panel.baseline,0);assert.equal(w.dynamicEdge.minimumGain,9);assert.deepEqual(w.dynamicEdge.targets,['d8','h6']);assert.ok(w.dynamicEdge.policy.every(b=>b.chosen==='f7d8'));assert.ok(w.dynamicEdge.alternativeRefutations.length>0);assert.equal(w.staticEdge,null);});
test('same variant set can reverse actual without misattributing force',()=>{const i={...df,move:df.advantageAlternative,advantageAlternative:df.move,advantageResourcePanel:dr.advantageResourceAnalysis.witness.panel},r=explainMove(i);assert.deepEqual(own(r),[]);assert.equal(r.advantageResourceAnalysis.nodes,dr.advantageResourceAnalysis.nodes);checkWitness(r.advantageResourceAnalysis.witness,r,i);});
test('insufficient existing lead cannot be a static edge',()=>{const fen=boardFen({h1:'K',d3:'R',h8:'k',a7:'n'}),i={...f,fen,history:{fen,moves:[]}},r=explainMove(i);assert.equal(r.advantageResourceAnalysis.witness.panel.baseline,2);assert.deepEqual(own(r),[]);checkWitness(r.advantageResourceAnalysis.witness,r,i);});
test('immediately capturable existing edge fails complete policy',()=>{const fen=boardFen({h1:'K',d3:'R',h8:'k',c4:'p'}),i={...f,fen,history:{fen,moves:[]}},r=explainMove(i),w=r.advantageResourceAnalysis.witness;assert.equal(w.panel.baseline,4);assert.ok(w.panel.variants[0].branches.some(b=>b.move==='c4d3'&&b.state.balance===-1));assert.deepEqual(own(r),[]);checkWitness(w,r,i);});
test('capture of checking unit refutes dynamic resource without discarded branches',()=>{const c=new Chess(df.fen);c.put({type:'b',color:'b'},'h5');const fen=c.fen(),i={...df,fen,history:{fen,moves:[]}},r=explainMove(i),w=r.advantageResourceAnalysis.witness;assert.ok(w.panel.variants[0].branches.some(b=>b.move==='h5f7'&&b.attempts.length===0));assert.deepEqual(own(r),[]);checkWitness(w,r,i);});
test('preexisting legal capture excludes new checking resource scope',()=>{const c=new Chess(df.fen);c.put({type:'p',color:'b'},'g6');const fen=c.fen(),i={...df,fen,history:{fen,moves:[]}},r=explainMove(i),w=r.advantageResourceAnalysis.witness;assert.equal(w.summaries[0].dynamic.passed,true);assert.equal(w.dynamicEdge,null);assert.deepEqual(own(r),[]);checkWitness(w,r,i);});
test('mate variant closes instead of vacuous material policy',()=>{const fen=boardFen({h6:'K',g6:'Q',h8:'k'}),i={...f,fen,history:{fen,moves:[]},move:'g6g7'},r=explainMove(i),w=r.advantageResourceAnalysis.witness;assert.equal(w.panel.variants[0].state.flags.mate,true);assert.deepEqual(w.panel.variants[0].legal,[]);assert.deepEqual(w.panel.variants[0].branches,[]);assert.deepEqual(own(r),[]);checkWitness(w,r,i);});
test('actual longer history and root en passant inventory retained',()=>{const start=boardFen({h1:'K',d3:'R',e5:'P',h8:'k',d7:'p'},'b'),c=new Chess(start);c.move('d7d5');const i={...f,fen:c.fen(),history:{fen:start,moves:['d7d5']}},r=explainMove(i),w=r.advantageResourceAnalysis.witness,ep=w.panel.legal.find(m=>m.enPassant);assert.equal(ep.move,'e5d6');assert.equal(ep.victim,'d5');checkWitness(w,r,i);});
for(const [name,mutate]of Object.entries({rootInventory:w=>w.panel.legal.pop(),variant:w=>w.panel.variants.pop(),enemyInventory:w=>w.panel.variants[0].legal.pop(),branch:w=>w.panel.variants[0].branches.pop(),actorInventory:w=>w.panel.variants[0].branches[0].legal.pop(),attempt:w=>w.panel.variants[0].branches[0].attempts.pop(),counterInventory:w=>w.panel.variants[0].branches[0].attempts[0].legal.pop(),counter:w=>w.panel.variants[0].branches[0].attempts[0].counters.pop(),balance:w=>w.panel.variants[0].branches[0].attempts[0].counters[0].balance=99,terminal:w=>w.panel.variants[0].branches[0].attempts[0].counters[0].flags.mate=true,baseline:w=>w.panel.baseline++,history:w=>w.panel.history.moves=['h1g1'],cost:w=>w.panel.nodes--,claim:w=>w.panel.claimContexts=['fiction'],summary:w=>w.summaries[0].stable.passed=false,selection:w=>w.staticEdge.policy[0].chosen='g1g2',minimum:w=>w.staticEdge.minimum++}))test('independent static proof mutation '+name,()=>{const r=structuredClone(sr);mutate(r.advantageResourceAnalysis.witness);assert.throws(()=>checkWitness(r.advantageResourceAnalysis.witness,r,f));});
for(const [name,mutate]of Object.entries({target:w=>w.dynamicEdge.targets=[],prior:w=>w.dynamicEdge.priorCaptures=['e5g6'],alternative:w=>w.dynamicEdge.alternative='e5f7',refutation:w=>w.dynamicEdge.alternativeRefutations=[],gain:w=>w.dynamicEdge.minimumGain++,policy:w=>w.dynamicEdge.policy[0].chosen='f7h6'}))test('independent dynamic proof mutation '+name,()=>{const r=structuredClone(dr);mutate(r.advantageResourceAnalysis.witness);assert.throws(()=>checkWitness(r.advantageResourceAnalysis.witness,r,df));});
test('caller admission and quality metadata cannot be altered',()=>{const i=structuredClone(di);i.advantageResourcePanel.variants[0].branches.pop();assert.throws(()=>explainMove(i));for(const mutate of [r=>own(r)[0].qualityClaim=true,r=>own(r)[0].text='Winning position',r=>r.events.pop(),r=>r.advantageResourceAnalysis.status='compared']){const r=structuredClone(dr);mutate(r);assert.throws(()=>checkWitness(r.advantageResourceAnalysis.witness,r,df));}});
